export default "const state={token:localStorage.getItem('chatlk_token'),user:JSON.parse(localStorage.getItem('chatlk_user')||'null'),chats:[],contacts:[],active:null,messages:[],socket:null,groupMembers:[],replyTo:null,typingTimer:null,reconnectTimer:null,recording:null,recordingChunks:[],recordingTimer:null,recordingStartedAt:0,call:null,filter:'all',searchQuery:''};\nconst app=document.querySelector('#app');\nconst api=async(path,options={})=>{const headers={Authorization:state.token?`Bearer ${state.token}`:'',...(options.headers||{})};if(!(options.body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch(`/api${path}`,{...options,headers});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Request failed');return data};\nconst esc=value=>String(value??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#039;'}[c]));\nconst displayName=user=>user?.display_name||user?.displayName||user?.username||'User';\nfunction applyTheme(){const saved=localStorage.getItem('chatlk_theme');document.body.classList.toggle('dark-mode',saved==='dark'||(!saved&&window.matchMedia?.('(prefers-color-scheme: dark)').matches));}\nfunction toggleTheme(){const dark=!document.body.classList.contains('dark-mode');localStorage.setItem('chatlk_theme',dark?'dark':'light');applyTheme();}\nlet deferredInstallPrompt=null;\nfunction isStandalone(){return window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true;}\nfunction showInstallNotice(){if(isStandalone()||document.querySelector('.install-notice'))return;const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);const notice=document.createElement('aside');notice.className='install-notice';notice.innerHTML='<div class=\"install-copy\"><strong>Install ChatLK</strong><span>'+(ios?'Add ChatLK to your Home Screen for a faster app experience.':'Install ChatLK on your phone for quick access and notifications.')+'</span></div><button class=\"install-now\" type=\"button\">Install</button><button class=\"install-dismiss\" type=\"button\" aria-label=\"Dismiss\">×</button>';document.body.append(notice);notice.querySelector('.install-dismiss').onclick=()=>{notice.remove();sessionStorage.setItem('chatlk_install_notice_dismissed','1')};notice.querySelector('.install-now').onclick=async()=>{if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;notice.remove()}else{notice.querySelector('.install-copy span').textContent=ios?'Tap Share, then Add to Home Screen.':'Use your browser menu and choose Install app or Add to Home screen.';notice.querySelector('.install-now').textContent='Got it'}};}\nfunction setupPWA(){if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;showInstallNotice()});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;document.querySelector('.install-notice')?.remove()});if(!isStandalone()&&!sessionStorage.getItem('chatlk_install_notice_dismissed'))setTimeout(showInstallNotice,900);}\nfunction auth(){app.innerHTML=`<section class=\"auth-screen\"><div class=\"card\"><div class=\"brand\">✦ ChatLK</div><p>Private, real-time conversations.</p><form id=\"login\"><div class=\"field\"><label>Username or phone</label><input name=\"identifier\" required></div><div class=\"field\"><label>Password</label><input name=\"password\" type=\"password\" required></div><button class=\"primary\">Sign in</button></form><p>New here? <button class=\"link\" id=\"show-register\">Create an account</button></p><p class=\"error\" id=\"error\"></p></div></section>`;document.querySelector('#login').onsubmit=login;document.querySelector('#show-register').onclick=register}\nfunction register(){app.innerHTML=`<section class=\"auth-screen\"><div class=\"card\"><div class=\"brand\">✦ ChatLK</div><form id=\"register\"><div class=\"field\"><label>Username</label><input name=\"username\" pattern=\"[A-Za-z0-9_]{3,20}\" required></div><div class=\"field\"><label>Phone (E.164)</label><input name=\"phone\" placeholder=\"+94771234567\" required></div><div class=\"field\"><label>Display name</label><input name=\"display_name\" required></div><div class=\"field\"><label>Password</label><input name=\"password\" type=\"password\" minlength=\"8\" required></div><button class=\"primary\">Create account</button></form><p>Already registered? <button class=\"link\" onclick=\"location.reload()\">Sign in</button></p><p class=\"error\" id=\"error\"></p></div></section>`;document.querySelector('#register').onsubmit=async e=>{e.preventDefault();try{const data=await api('/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});saveSession(data);render()}catch(error){document.querySelector('#error').textContent=error.message}}}\nasync function login(e){e.preventDefault();try{const data=await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});saveSession(data);render()}catch(error){document.querySelector('#error').textContent=error.message}}\nfunction saveSession(data){state.token=data.token;state.user=data.user;localStorage.setItem('chatlk_token',state.token);localStorage.setItem('chatlk_user',JSON.stringify(state.user))}\nasync function render(){if(!state.token)return auth();try{const [chatData,contactData,me]=await Promise.all([api('/chats'),api('/contacts'),api('/users/me')]);state.chats=chatData.chats||[];state.contacts=contactData.contacts||[];state.user=me.user||state.user;localStorage.setItem('chatlk_user',JSON.stringify(state.user))}catch(error){state.token=null;localStorage.removeItem('chatlk_token');return auth()}app.innerHTML=`<div class=\"shell\"><aside class=\"sidebar\"><header class=\"home-header\"><div class=\"brand-word\">ChatLK</div><div class=\"header-actions\"><button class=\"icon-button\" id=\"camera-btn\" aria-label=\"Camera\">▣</button><button class=\"icon-button\" id=\"menu-btn\" aria-label=\"Menu\">⋮</button></div></header><div class=\"home-tools\"><label class=\"search-wrap\"><span aria-hidden=\"true\">⌕</span><input class=\"search\" id=\"search\" placeholder=\"Search chats\" aria-label=\"Search chats\"></label><div class=\"filter-row\" role=\"tablist\" aria-label=\"Chat filters\"><button class=\"filter-chip active\" data-filter=\"all\">All</button><button class=\"filter-chip\" data-filter=\"unread\">Unread <span class=\"count-badge\">0</span></button><button class=\"filter-chip\" data-filter=\"favorites\">Favorites</button><button class=\"filter-chip\" data-filter=\"groups\">Groups</button><button class=\"filter-chip add-filter\" id=\"new-chat\" aria-label=\"Start a new chat\">＋</button></div></div><div class=\"quick-row\"><button class=\"quick-item\"><span class=\"quick-icon\">▣</span><strong>Locked chats</strong></button><button class=\"quick-item\"><span class=\"quick-icon\">▾</span><strong>Archived</strong><span class=\"quick-count\">0</span></button></div><div id=\"chat-list\"></div><div class=\"sidebar-actions\"><button class=\"outline-btn\" id=\"profile-btn\">Profile</button><button class=\"outline-btn\" id=\"contacts-btn\">Contacts</button><button class=\"outline-btn\" id=\"group-btn\">＋ Group</button><button class=\"link\" id=\"logout\">Log out</button></div><nav class=\"bottom-nav\" aria-label=\"Main navigation\"><button class=\"nav-item active\"><span>▤</span><b>Chats</b></button><button class=\"nav-item\" id=\"updates-btn\"><span>◉</span><b>Updates</b></button><button class=\"nav-item\"><span>♧</span><b>Communities</b></button><button class=\"nav-item\"><span>⌕</span><b>Calls</b></button></nav><button class=\"fab\" id=\"fab-new\" aria-label=\"New chat\">＋</button></aside><section class=\"main\"><header class=\"topbar chat-topbar\"><button class=\"mobile-back\" id=\"mobile-back\" aria-label=\"Back to chats\">‹</button><div class=\"avatar chat-avatar\">${esc(displayName(state.user)[0])}</div><div class=\"topbar-copy\"><strong id=\"chat-title\">Select a chat</strong><div id=\"presence\">last seen recently</div></div><div class=\"chat-actions\"><button type=\"button\" id=\"video-call-btn\" aria-label=\"Video call\">▣</button><button type=\"button\" id=\"voice-call-btn\" aria-label=\"Voice call\">☎</button><button type=\"button\" aria-label=\"More options\">⋮</button></div></header><div class=\"messages\" id=\"messages\"><div class=\"empty\">Choose a conversation to begin.</div></div><div id=\"reply-preview\" class=\"reply-preview hidden\"></div><form class=\"composer whatsapp-composer\" id=\"composer\"><button type=\"button\" class=\"composer-icon\" id=\"emoji-btn\" aria-label=\"Emoji\">☺</button><input name=\"text\" placeholder=\"Type a message\" autocomplete=\"off\" aria-label=\"Message\"><button type=\"button\" class=\"composer-icon\" id=\"attach-btn\" aria-label=\"Attach file\">⊕</button><input type=\"file\" id=\"media-input\" class=\"hidden\" accept=\"image/jpeg,image/png,image/webp,image/gif,application/pdf\"><button type=\"button\" class=\"composer-icon\" id=\"camera-chat-btn\" aria-label=\"Camera\">▣</button><button type=\"button\" class=\"mic-send\" id=\"voice-btn\" aria-label=\"Record voice note\">●</button></form><div id=\"call-overlay\" class=\"call-overlay hidden\"><video id=\"remote-video\" class=\"remote-video\" autoplay playsinline></video><video id=\"local-video\" class=\"local-video\" autoplay muted playsinline></video><div class=\"call-status\" id=\"call-status\">Calling…</div><div class=\"call-controls\"><button type=\"button\" id=\"mute-call\" aria-label=\"Mute microphone\">🎙</button><button type=\"button\" id=\"share-screen\" aria-label=\"Share screen\">▣</button><button type=\"button\" id=\"end-call\" class=\"end-call\" aria-label=\"End call\">☎</button></div></div></section></div>`;document.querySelector('#logout').onclick=logout;document.querySelector('#menu-btn').onclick=toggleTheme;document.querySelector('#menu-btn').title='Toggle dark mode';document.querySelector('#updates-btn').onclick=showStatuses;document.querySelector('#profile-btn').onclick=showProfile;document.querySelector('#new-chat').onclick=showNewChat;document.querySelector('#fab-new').onclick=showNewChat;document.querySelector('#contacts-btn').onclick=showContacts;document.querySelector('#group-btn').onclick=showGroup;document.querySelector('#mobile-back').onclick=()=>document.querySelector('.shell').classList.remove('chat-open');document.querySelector('.chat-avatar').onclick=showChatInfo;document.querySelector('#chat-title').onclick=showChatInfo;document.querySelector('#video-call-btn').onclick=()=>startCall('video');document.querySelector('#voice-call-btn').onclick=()=>startCall('audio');setupCallUi();document.querySelector('#composer').onsubmit=send;document.querySelector('#composer input').oninput=handleTyping;document.querySelector('#emoji-btn').onclick=()=>{const input=document.querySelector('#composer input');input.value+='🙂';input.focus()};document.querySelector('#attach-btn').onclick=()=>document.querySelector('#media-input').click();document.querySelector('#media-input').onchange=e=>{if(e.target.files[0])uploadMedia(e.target.files[0]);e.target.value=''};document.querySelector('#camera-chat-btn').onclick=()=>document.querySelector('#presence').textContent='Camera is coming soon';document.querySelector('#voice-btn').onclick=toggleVoiceRecording;document.querySelector('#search').oninput=e=>{state.searchQuery=e.target.value.trim().toLowerCase();drawChats()};document.querySelectorAll('.filter-chip[data-filter]').forEach(button=>button.onclick=()=>{state.filter=button.dataset.filter;document.querySelectorAll('.filter-chip').forEach(item=>item.classList.toggle('active',item===button));drawChats()});drawChats()}\nfunction logout(){state.socket?.close();state.token=null;state.user=null;localStorage.removeItem('chatlk_token');localStorage.removeItem('chatlk_user');auth()}\nfunction drawChats(){const list=document.querySelector('#chat-list');if(!list)return;const chats=state.chats.filter(chat=>{const name=(chat.name||'Direct chat').toLowerCase();const matches=!state.searchQuery||name.includes(state.searchQuery)||(chat.last_message||'').toLowerCase().includes(state.searchQuery);const filterMatch=state.filter==='all'||(state.filter==='groups'&&chat.type==='group')||(state.filter==='unread'&&Number(chat.unread_count)>0);return matches&&filterMatch});const unreadTotal=state.chats.reduce((sum,chat)=>sum+Number(chat.unread_count||0),0);const badge=document.querySelector('.count-badge');if(badge)badge.textContent=unreadTotal||'';if(!chats.length){list.innerHTML='<p class=\"empty chat-empty\">No conversations yet.<br>Tap <b>＋</b> to begin.</p>';return}list.replaceChildren();for(const chat of chats){const item=document.createElement('button');item.className='chat-item '+(Number(chat.unread_count)>0?'has-unread':'');const name=chat.name||'Direct chat';const time=chat.last_message_at?new Date(chat.last_message_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}):'';const mine=chat.last_message_sender_id===state.user?.id;const preview=chat.last_message?(mine?'You: ':'')+(chat.last_message):'No messages yet';item.innerHTML='<span class=\"avatar\">'+esc(name[0])+'</span><span class=\"chat-meta\"><strong>'+esc(name)+'</strong><span>'+esc(preview)+'</span></span><span class=\"chat-side\"><span class=\"chat-time\">'+esc(time)+'</span>'+(Number(chat.unread_count)>0?'<span class=\"unread-badge\">'+chat.unread_count+'</span>':'')+'</span>';item.onclick=()=>openChat(chat);list.append(item)}}\nfunction modal(title,body){const node=document.createElement('div');node.className='modal-backdrop';node.innerHTML=`<section class=\"modal card\" role=\"dialog\" aria-modal=\"true\"><h2>${title}</h2>${body}<button class=\"link\" id=\"close-modal\">Cancel</button></section>`;document.body.append(node);node.querySelector('#close-modal').onclick=()=>node.remove();return node}\nfunction renderStatusMedia(status,box){if(!status.media_url)return;loadMedia(status.media_url).then(url=>{if(status.media_type&&status.media_type.startsWith('video/')){const video=document.createElement('video');video.src=url;video.controls=true;video.playsInline=true;video.className='status-media';box.prepend(video)}else{const image=document.createElement('img');image.src=url;image.alt='Status media';image.className='status-media';box.prepend(image)}}).catch(()=>{})}\nasync function createStatus(event,modalNode){event.preventDefault();const form=event.target;const text=form.elements.text.value.trim();const file=form.elements.file.files[0];const error=modalNode.querySelector('#status-error');try{let mediaUrl=null,mediaType=null;if(file){const upload=new FormData();upload.append('file',file);const result=await api('/media/upload',{method:'POST',body:upload});mediaUrl=result.url;mediaType=file.type}await api('/statuses',{method:'POST',body:JSON.stringify({text,mediaUrl,mediaType})});modalNode.remove();showStatuses()}catch(err){error.textContent=err.message}}\nasync function showStatuses(){try{const data=await api('/statuses');const statuses=data.statuses||[];const cards=statuses.map(status=>{const own=status.user_id===state.user?.id;const time=new Date(status.created_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});return `<article class=\"status-card ${status.viewed?'viewed':''}\" data-status-id=\"${status.id}\"><div class=\"status-head\"><div class=\"avatar status-avatar\">${esc((status.display_name||status.username||'U')[0])}</div><div><strong>${esc(own?'My status':status.display_name||status.username)}</strong><span>${esc(time)} · ${Math.max(0,Math.round((status.expires_at-Date.now())/3600000))}h left</span></div>${own?'<button type=\"button\" class=\"danger-btn status-delete\">Delete</button>':''}</div><div class=\"status-content\">${status.text?`<p>${esc(status.text)}</p>`:''}</div>${own?`<small class=\"status-viewers\">${status.viewer_count||0} views</small>`:''}</article>`}).join('');const m=modal('Updates / Status',`<form id=\"status-form\" class=\"inline-form\"><textarea name=\"text\" maxlength=\"700\" rows=\"2\" placeholder=\"Type a status…\"></textarea><input type=\"file\" name=\"file\" accept=\"image/jpeg,image/png,image/webp,image/gif,video/mp4\"><button class=\"primary\">Post status</button><p class=\"error\" id=\"status-error\"></p></form><div class=\"status-list\">${cards||'<p class=\"empty\">No active statuses yet.</p>'}</div>`);m.querySelector('#status-form').onsubmit=e=>createStatus(e,m);for(const status of statuses){const card=m.querySelector(`[data-status-id=\"${status.id}\"]`);if(status.media_url)renderStatusMedia(status,card.querySelector('.status-content'));card.onclick=async e=>{if(e.target.closest('.status-delete'))return;await api(`/statuses/${status.id}/view`,{method:'POST'}).catch(()=>{});card.classList.add('viewed')};card.querySelector('.status-delete')?.addEventListener('click',async()=>{await api(`/statuses/${status.id}`,{method:'DELETE'});m.remove();showStatuses()})}}catch(error){alert(error.message)}}\nfunction showProfile(){const u=state.user||{};const m=modal('Your profile',`<div class=\"profile-hero\"><div class=\"profile-avatar-wrap\"><div class=\"avatar profile-avatar\" id=\"profile-avatar\">${esc(displayName(u)[0])}</div><label class=\"avatar-upload\" aria-label=\"Change profile photo\">＋<input type=\"file\" id=\"avatar-input\" accept=\"image/jpeg,image/png,image/webp,image/gif\"></label></div><div><h3>${esc(displayName(u))}</h3><p>@${esc(u.username)}${(u.is_verified||u.isVerified)?' · ✓ Verified':''}</p></div></div><form id=\"profile-form\" class=\"inline-form\"><div class=\"field\"><label>Display name</label><input name=\"display_name\" maxlength=\"80\" value=\"${esc((u.display_name||u.displayName))}\" required></div><div class=\"field\"><label>About / bio</label><textarea name=\"bio\" maxlength=\"500\" rows=\"3\">${esc(u.bio)}</textarea></div><div class=\"field\"><label>Language</label><select name=\"language\"><option value=\"si\" ${u.language==='si'?'selected':''}>සිංහල</option><option value=\"ta\" ${u.language==='ta'?'selected':''}>தமிழ்</option><option value=\"en\" ${u.language==='en'?'selected':''}>English</option></select></div><button class=\"primary\">Save profile</button><p class=\"error\" id=\"profile-error\"></p></form><div class=\"profile-details\"><span>Phone</span><b>${esc(u.phone||'Not available')}</b><span>Last seen</span><b>${(u.last_seen||u.lastSeen)?new Date((u.last_seen||u.lastSeen)).toLocaleString():'Recently active'}</b></div>`);if((u.avatar_url||u.avatarUrl))loadMedia((u.avatar_url||u.avatarUrl)).then(url=>{m.querySelector('#profile-avatar').innerHTML=`<img src=\"${url}\" alt=\"Profile photo\">`}).catch(()=>{});m.querySelector('#avatar-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const form=new FormData();form.append('file',file);const data=await api('/users/me/avatar',{method:'POST',body:form});state.user.avatar_url=data.url;const url=await loadMedia(data.url);m.querySelector('#profile-avatar').innerHTML=`<img src=\"${url}\" alt=\"Profile photo\">`}catch(error){m.querySelector('#profile-error').textContent=error.message}};m.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();try{const data=await api('/users/me',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.user=data.user;localStorage.setItem('chatlk_user',JSON.stringify(state.user));m.remove();render()}catch(error){m.querySelector('#profile-error').textContent=error.message}}}\nfunction showNewChat(){const m=modal('Start a new chat',`<p>Search by username, phone, or display name.</p><input class=\"search\" id=\"user-query\" placeholder=\"e.g. user_name or +9477...\" autofocus><div id=\"user-results\"><p class=\"empty\">Type at least 2 characters.</p></div>`);m.querySelector('#user-query').oninput=searchUsers}\nlet searchTimer;function searchUsers(e){clearTimeout(searchTimer);const value=e.target.value.trim(),results=e.target.closest('.modal').querySelector('#user-results');if(value.length<2){results.innerHTML='<p class=\"empty\">Type at least 2 characters.</p>';return}searchTimer=setTimeout(async()=>{try{const data=await api(`/users/search?q=${encodeURIComponent(value)}`);results.replaceChildren();if(!data.users?.length){results.innerHTML='<p class=\"empty\">No users found.</p>';return}for(const user of data.users){const button=document.createElement('button');button.className='chat-item';button.innerHTML=`<span class=\"avatar\">${esc(displayName(user)[0])}</span><span class=\"chat-meta\"><strong>${esc(displayName(user))}</strong><span>@${esc(user.username)}</span></span>`;button.onclick=()=>createDirectChat(user);results.append(button)}}catch(error){results.innerHTML=`<p class=\"error\">${esc(error.message)}</p>`}},250)}\nasync function createDirectChat(user){try{const data=await api('/chats',{method:'POST',body:JSON.stringify({type:'direct',participantIds:[user.id]})});document.querySelector('.modal-backdrop')?.remove();await refreshChats();const chat=state.chats.find(item=>item.id===data.id);if(chat)openChat(chat)}catch(error){const results=document.querySelector('.modal-backdrop #user-results');if(results)results.innerHTML=`<p class=\"error\">${esc(error.message)}</p>`}}\nasync function refreshChats(){const data=await api('/chats');state.chats=data.chats||[];drawChats()}\nasync function refreshContacts(){const data=await api('/contacts');state.contacts=data.contacts||[]}\nfunction showContacts(){const m=modal('Contacts',`<p>Add people by username or phone. You can block or remove saved contacts.</p><form id=\"add-contact\" class=\"inline-form\"><input name=\"identifier\" placeholder=\"username or +9477...\" required><input name=\"nickname\" placeholder=\"Nickname (optional)\"><button class=\"primary\">Add contact</button></form><p class=\"error\" id=\"contact-error\"></p><div id=\"invite-area\" class=\"invite-area hidden\"></div><div id=\"contact-list\"></div>`);m.querySelector('#add-contact').onsubmit=addContact;drawContacts(m)}\nfunction drawContacts(m){const list=m.querySelector('#contact-list');if(!state.contacts.length){list.innerHTML='<p class=\"empty\">No contacts saved yet.</p>';return}list.replaceChildren();for(const contact of state.contacts){const item=document.createElement('div');item.className='contact-row';item.innerHTML=`<span class=\"avatar\">${esc(displayName(contact)[0])}</span><span class=\"chat-meta\"><strong>${esc(contact.nickname||displayName(contact))}</strong><span>@${esc(contact.username)} · ${contact.is_blocked?'Blocked':'Active'}</span></span><button class=\"outline-btn contact-chat\">Chat</button><button class=\"danger-btn contact-block\">${contact.is_blocked?'Unblock':'Block'}</button><button class=\"danger-btn contact-remove\">Remove</button>`;item.querySelector('.contact-chat').onclick=()=>createDirectChat(contact);item.querySelector('.contact-block').onclick=()=>updateContact(contact.id,!contact.is_blocked,m);item.querySelector('.contact-remove').onclick=()=>removeContact(contact.id,m);list.append(item)}}\nasync function addContact(e){e.preventDefault();const m=e.target.closest('.modal');try{await api('/contacts',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await refreshContacts();e.target.reset();drawContacts(m)}catch(error){const value=e.target.elements.identifier.value.trim();m.querySelector('#contact-error').textContent=error.message;const area=m.querySelector('#invite-area');area.className='invite-area';area.innerHTML=`<span>${esc(value)} is not registered on ChatLK.</span><button type=\"button\" class=\"primary invite-button\">Invite</button>`;area.querySelector('.invite-button').onclick=()=>inviteContact(value)}}\nasync function updateContact(id,isBlocked,m){try{await api(`/contacts/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({is_blocked:isBlocked})});await refreshContacts();drawContacts(m)}catch(error){m.querySelector('#contact-error').textContent=error.message}}\nasync function removeContact(id,m){try{await api(`/contacts/${encodeURIComponent(id)}`,{method:'DELETE'});await refreshContacts();drawContacts(m)}catch(error){m.querySelector('#contact-error').textContent=error.message}}\nfunction showGroup(){state.groupMembers=[];const m=modal('Create a group',`<p>Select contacts or search users to add members.</p><div class=\"field\"><label>Group name</label><input id=\"group-name\" maxlength=\"120\" placeholder=\"e.g. Family\"></div><input class=\"search\" id=\"group-query\" placeholder=\"Search users\"><div id=\"group-selected\" class=\"selected-users\"></div><div id=\"group-results\"><p class=\"empty\">Select at least one other user.</p></div><p class=\"error\" id=\"group-error\"></p><button class=\"primary\" id=\"create-group\">Create group</button>`);m.querySelector('#group-query').oninput=e=>searchGroupUsers(e,m);m.querySelector('#create-group').onclick=()=>createGroup(m)}\nfunction drawSelected(m){const box=m.querySelector('#group-selected');box.replaceChildren();for(const user of state.groupMembers){const chip=document.createElement('span');chip.className='user-chip';chip.textContent=displayName(user);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label',`Remove ${displayName(user)}`);remove.onclick=()=>{state.groupMembers=state.groupMembers.filter(item=>item.id!==user.id);drawSelected(m)};chip.append(remove);box.append(chip)}}\nlet groupTimer;function searchGroupUsers(e,m){clearTimeout(groupTimer);const value=e.target.value.trim(),results=m.querySelector('#group-results');if(value.length<2){results.innerHTML='<p class=\"empty\">Type at least 2 characters.</p>';return}groupTimer=setTimeout(async()=>{try{const data=await api(`/users/search?q=${encodeURIComponent(value)}`);results.replaceChildren();for(const user of data.users||[]){if(state.groupMembers.some(item=>item.id===user.id))continue;const button=document.createElement('button');button.className='chat-item';button.innerHTML=`<span class=\"avatar\">${esc(displayName(user)[0])}</span><span class=\"chat-meta\"><strong>${esc(displayName(user))}</strong><span>@${esc(user.username)}</span></span>`;button.onclick=()=>{state.groupMembers.push(user);drawSelected(m);button.remove()};results.append(button)}if(!results.children.length)results.innerHTML='<p class=\"empty\">No users found.</p>'}catch(error){results.innerHTML=`<p class=\"error\">${esc(error.message)}</p>`}},250)}\nasync function createGroup(m){const name=m.querySelector('#group-name').value.trim();if(!name||!state.groupMembers.length){m.querySelector('#group-error').textContent='Enter a group name and select at least one member.';return}try{const data=await api('/chats',{method:'POST',body:JSON.stringify({type:'group',name,participantIds:state.groupMembers.map(user=>user.id)})});m.remove();await refreshChats();const chat=state.chats.find(item=>item.id===data.id);if(chat)openChat(chat)}catch(error){m.querySelector('#group-error').textContent=error.message}}\nasync function openChat(chat){state.active=chat;state.replyTo=null;document.querySelector('.shell').classList.add('chat-open');document.querySelector('#chat-title').textContent=chat.name||'Direct chat';document.querySelector('#presence').textContent='Connecting…';try{const data=await api(`/chats/${chat.id}/messages`);state.messages=(data.messages||[]).reverse();drawMessages();const unread=state.messages.filter(message=>{const sender=message.sender_id||message.senderId;return sender!==state.user?.id&&message.status!=='read'});if(unread.length)await Promise.all(unread.map(markRead));await refreshChats();connectSocket(chat)}catch(error){document.querySelector('#presence').textContent=error.message}}\nfunction connectSocket(chat){state.socket?.close();const protocol=location.protocol==='https:'?'wss:':'ws:';state.socket=new WebSocket(`${protocol}//${location.host}/ws?userId=${encodeURIComponent(state.user.id)}&chatId=${encodeURIComponent(chat.id)}&token=${encodeURIComponent(state.token)}`);state.socket.onopen=()=>document.querySelector('#presence').textContent='Online';state.socket.onclose=()=>{if(state.active?.id===chat.id){document.querySelector('#presence').textContent='Reconnecting…';clearTimeout(state.reconnectTimer);state.reconnectTimer=setTimeout(()=>connectSocket(chat),1500)}};state.socket.onerror=()=>document.querySelector('#presence').textContent='Connection error';state.socket.onmessage=event=>{const data=JSON.parse(event.data);if(data.type==='message'){state.messages.push(data.message);drawMessages();markRead(data.message)}if(data.type==='presence'&&data.userId!==state.user.id)document.querySelector('#presence').textContent=data.status==='online'?'Online':'Offline';if(data.type==='typing'&&data.userId!==state.user.id)document.querySelector('#presence').textContent=data.isTyping?'Typing…':'Online';if(data.type==='read'){const message=state.messages.find(item=>item.id===data.messageId);if(message)message.status='read';drawMessages()}if(data.type==='call-offer'&&data.userId!==state.user.id)receiveCall(data.payload,data.userId);if(data.type==='call-answer'&&state.call?.pc)data.payload&&state.call.pc.setRemoteDescription(data.payload).catch(()=>{});if(data.type==='ice-candidate'&&state.call?.pc&&data.payload)state.call.pc.addIceCandidate(data.payload).catch(()=>{});if(data.type==='call-end')endCall(false)}}\nfunction drawMessages(){const container=document.querySelector('#messages');if(!container)return;container.replaceChildren();if(!state.messages.length){container.innerHTML='<div class=\"empty\">No messages yet. Say hello.</div>';return}let lastDay='';for(const message of state.messages){const date=new Date(message.created_at||message.createdAt);const day=date.toLocaleDateString();if(day!==lastDay){const divider=document.createElement('div');divider.className='date-divider';divider.textContent=day;container.append(divider);lastDay=day}const mine=message.sender_id===state.user?.id||message.senderId===state.user?.id;const bubble=document.createElement('article');bubble.className=`bubble whatsapp-bubble ${mine?'sent':''}`;bubble.dataset.id=message.id;if(!mine&&state.active?.type==='group'){const sender=document.createElement('strong');sender.className='sender-name';sender.textContent=message.sender_name||message.senderName||'Member';bubble.append(sender)}const text=document.createElement('p');text.textContent=message.text||'[media]';if(message.media_url||message.mediaUrl){const mediaUrl=message.media_url||message.mediaUrl;if(message.message_type==='image'||message.messageType==='image'){text.textContent='Loading image…';loadMedia(mediaUrl).then(url=>{const image=document.createElement('img');image.className='message-image';image.src=url;image.alt=message.text||'Shared image';text.replaceWith(image)}).catch(()=>text.textContent='Image unavailable')}else if(message.message_type==='audio'||message.messageType==='audio'){text.textContent='Loading voice note…';loadMedia(mediaUrl).then(url=>{const audio=document.createElement('audio');audio.className='voice-player';audio.controls=true;audio.preload='metadata';audio.src=url;text.replaceWith(audio)}).catch(()=>text.textContent='Voice note unavailable')}else{const link=document.createElement('button');link.type='button';link.className='document-link';link.textContent=`▧ ${message.text||'Download document'}`;link.onclick=async()=>{try{const url=await loadMedia(mediaUrl);const anchor=document.createElement('a');anchor.href=url;anchor.download=message.text||'download';anchor.click()}catch(error){document.querySelector('#presence').textContent=error.message}};text.replaceWith(link)}}const meta=document.createElement('small');const ticks=message.status==='read'?'✓✓':message.status==='delivered'?'✓✓':'✓';meta.innerHTML=`${date.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}${message.is_edited?' · edited':''}${mine?` <span class=\"message-ticks ${message.status==='read'?'read':''}\" aria-label=\"${message.status||'sent'}\">${ticks}</span>`:''}`;bubble.append(text,meta);bubble.onclick=()=>showMessageActions(message,bubble);container.append(bubble)}container.scrollTop=container.scrollHeight}\nfunction showMessageActions(message,bubble){document.querySelector('.message-actions')?.remove();const mine=message.sender_id===state.user?.id||message.senderId===state.user?.id;const menu=document.createElement('div');menu.className='message-actions';menu.innerHTML=`<button data-action=\"reply\">Reply</button>${mine?'<button data-action=\"edit\">Edit</button><button data-action=\"delete\">Delete</button>':''}<button data-action=\"copy\">Copy</button>`;bubble.append(menu);menu.onclick=async e=>{const action=e.target.dataset.action;if(action==='reply'){state.replyTo=message;drawReplyPreview()}if(action==='copy')await navigator.clipboard?.writeText(message.text||'');if(action==='edit')editMessage(message);if(action==='delete')deleteMessage(message);menu.remove()};setTimeout(()=>menu.remove(),4000)}\nfunction drawReplyPreview(){const box=document.querySelector('#reply-preview');if(!state.replyTo){box.className='reply-preview hidden';return}box.className='reply-preview';box.innerHTML=`Replying to: <b>${esc((state.replyTo.text||'[media]').slice(0,100))}</b><button type=\"button\" id=\"cancel-reply\">×</button>`;box.querySelector('#cancel-reply').onclick=()=>{state.replyTo=null;drawReplyPreview()}}\nasync function editMessage(message){const text=prompt('Edit message',message.text||'');if(text===null||!text.trim())return;try{await api(`/messages/${message.id}`,{method:'PUT',body:JSON.stringify({text})});message.text=text.trim();message.is_edited=1;drawMessages()}catch(error){alert(error.message)}}\nasync function deleteMessage(message){if(!confirm('Delete this message?'))return;try{await api(`/messages/${message.id}`,{method:'DELETE'});state.messages=state.messages.filter(item=>item.id!==message.id);drawMessages()}catch(error){alert(error.message)}}\nfunction handleTyping(e){if(!state.socket||state.socket.readyState!==WebSocket.OPEN)return;state.socket.send(JSON.stringify({type:'typing',isTyping:Boolean(e.target.value.trim())}));clearTimeout(state.typingTimer);state.typingTimer=setTimeout(()=>state.socket?.send(JSON.stringify({type:'typing',isTyping:false})),900)}\nfunction inviteContact(phone){const text=`Join me on ChatLK: ${location.origin}`;const link=`https://wa.me/${phone.replace(/[^0-9]/g,'')}?text=${encodeURIComponent(text)}`;if(navigator.share)navigator.share({title:'Join ChatLK',text,url:link}).catch(()=>{});else{navigator.clipboard?.writeText(link);alert('Invite link copied to clipboard.')}}\nfunction showChatInfo(){if(!state.active)return;api(`/chats/${state.active.id}`).then(data=>{const people=data.participants||[];const peopleHtml=people.map(user=>{const seen=user.last_seen?new Date(user.last_seen).toLocaleString():'Recently active';return `<div class=\"detail-person\"><div class=\"avatar detail-avatar\">${esc(displayName(user)[0])}</div><div><b>${esc(displayName(user))}</b><span>@${esc(user.username)} · ${esc(user.role)}</span><span>${esc(user.phone||'Phone unavailable')}</span><span>${esc(user.bio||'No bio added')}</span><span>${esc(user.language==='si'?'සිංහල':user.language==='ta'?'தமிழ்':'English')} · ${esc(seen)}</span></div></div>`}).join('');const heroName=state.active.name||'Direct chat';const modalNode=modal(state.active.type==='group'?'Group details':'User details',`<div class=\"chat-detail-hero\"><div class=\"avatar large-avatar\" id=\"chat-detail-avatar\">${esc(heroName[0])}</div><h3>${esc(heroName)}</h3><p>${state.active.type==='group'?'Group conversation':'Profile and contact details'}</p></div><div class=\"detail-list\">${peopleHtml}</div>`);const first=people.find(user=>user.id!==state.user?.id);if(first?.avatar_url)loadMedia(first.avatar_url).then(url=>{const image=document.createElement('img');image.src=url;image.alt=displayName(first);modalNode.querySelector('#chat-detail-avatar').replaceChildren(image)}).catch(()=>{})}).catch(error=>alert(error.message))}\nfunction updateRecordingUI(){const button=document.querySelector('#voice-btn');if(!button)return;if(state.recording){button.classList.add('recording');button.textContent='■';button.setAttribute('aria-label','Stop recording');const seconds=Math.floor((Date.now()-state.recordingStartedAt)/1000);document.querySelector('#presence').textContent=`Recording audio… 0:${String(seconds).padStart(2,'0')}`;}}\nasync function toggleVoiceRecording(){if(state.recording){state.recording.stop();return}if(!state.active){document.querySelector('#presence').textContent='Open a chat to record a voice note';return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){document.querySelector('#presence').textContent='Voice recording is not supported in this browser';return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg'].find(type=>MediaRecorder.isTypeSupported(type))||'';const recorder=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream);state.recording=recorder;state.recordingChunks=[];state.recordingStartedAt=Date.now();recorder.ondataavailable=e=>{if(e.data.size)state.recordingChunks.push(e.data)};recorder.onstop=async()=>{clearInterval(state.recordingTimer);stream.getTracks().forEach(track=>track.stop());const blob=new Blob(state.recordingChunks,{type:recorder.mimeType||'audio/webm'});state.recording=null;state.recordingChunks=[];const button=document.querySelector('#voice-btn');if(button){button.classList.remove('recording');button.textContent='●';button.setAttribute('aria-label','Record voice note')}if(blob.size>0)await uploadVoice(blob);else document.querySelector('#presence').textContent='Online'};recorder.start();state.recordingTimer=setInterval(updateRecordingUI,250);updateRecordingUI()}catch(error){document.querySelector('#presence').textContent=error.name==='NotAllowedError'?'Microphone permission is required':error.message}}\nasync function uploadVoice(blob){const status=document.querySelector('#presence');status.textContent='Uploading voice note…';try{const form=new FormData();form.append('file',blob,`voice-note-${Date.now()}.${blob.type.includes('mp4')?'mp4':blob.type.includes('ogg')?'ogg':'webm'}`);const uploaded=await api('/media/upload',{method:'POST',body:form});const payload={text:'Voice message',mediaUrl:uploaded.url,messageType:'audio',mediaSize:blob.size};if(state.socket?.readyState===WebSocket.OPEN)state.socket.send(JSON.stringify({type:'message',...payload}));else{const data=await api(`/chats/${state.active.id}/messages`,{method:'POST',body:JSON.stringify(payload)});state.messages.push(data.message);drawMessages()}status.textContent='Online'}catch(error){status.textContent=error.message}}\nasync function uploadMedia(file){if(!state.active)return;const status=document.querySelector('#presence');status.textContent='Uploading…';try{const form=new FormData();form.append('file',file);const uploaded=await api('/media/upload',{method:'POST',body:form});const payload={text:file.name,mediaUrl:uploaded.url,messageType:file.type.startsWith('image/')?'image':'file',mediaSize:file.size};if(state.socket?.readyState===WebSocket.OPEN)state.socket.send(JSON.stringify({type:'message',...payload}));else{const data=await api(`/chats/${state.active.id}/messages`,{method:'POST',body:JSON.stringify(payload)});state.messages.push(data.message);drawMessages()}status.textContent='Online';}catch(error){status.textContent=error.message}}\nasync function loadMedia(url){const response=await fetch(url,{headers:{Authorization:state.token?`Bearer ${state.token}`:''}});if(!response.ok)throw new Error('Unable to load media');return URL.createObjectURL(await response.blob())}\nasync function markRead(message){if(!message?.id)return;try{await api(`/messages/${message.id}/read`,{method:'POST'});state.socket?.send(JSON.stringify({type:'read',messageId:message.id}))}catch{}}\nasync function send(e){e.preventDefault();const input=e.target.elements.text;if(!state.active||!input.value.trim())return;const text=input.value.trim();const payload={text,replyToId:state.replyTo?.id||null};try{if(state.socket?.readyState===WebSocket.OPEN)state.socket.send(JSON.stringify({type:'message',...payload}));else{const data=await api(`/chats/${state.active.id}/messages`,{method:'POST',body:JSON.stringify(payload)});state.messages.push(data.message);drawMessages()}input.value='';state.replyTo=null;drawReplyPreview();await refreshChats()}catch(error){document.querySelector('#presence').textContent=error.message}}\napplyTheme();\nsetupPWA();\nrender();\n";
